  // ═════════ Compléments : chaque chapitre atteint 20 questions, et la 5e garde 20 questions de conjugaison sans subjonctif ═════════
  const T = window.MATIERES_LANGUES || {};
  function plus(id, fr, en, es){
    const c = (M.trouver('francais') || { chapitres:[] }).chapitres.find(x => x.id === id); if(!c || !Array.isArray(c.banque)) return;
    const k = 'francais/' + id, n0 = c.banque.length;
    for(const [l, q] of [['en', en], ['es', es]]){ const t = T[l] && T[l].q && T[l].q[k]; if(t && (t.length !== n0 || q.length !== fr.length)) return; }
    c.banque.push(...fr); for(const [l, q] of [['en', en], ['es', es]]){ const t = T[l] && T[l].q && T[l].q[k]; if(t) t.push(...q); }
    if(c.nivQ) c.nivQ = c.banque.map((_, i) => i < n0 ? c.nivQ[i] : c.niv.slice());
  }

